import { useRef, useState } from "react";
import { FiCopy, FiPlusCircle, FiWifi } from "react-icons/fi";
import { convertTftToPoint } from "../../../utils/quizRewardRate";
import { token_address, ttt_token_address } from "../../../contract/config";
import { getWalletErrorMessage } from "../../../utils/walletErrors";
import WalletRecovery from "../../../components/WalletRecovery";
import MetaMaskMobileLink from "../../../components/MetaMaskMobileLink";

function User_card(props) {
    const operationInFlight = useRef(false);
    const [busy, setBusy] = useState("");
    const [message, setMessage] = useState("");
    const [failure, setFailure] = useState(null);
    const [manualToken, setManualToken] = useState(null);
    const [providerMissing, setProviderMissing] = useState(false);
    const isCurrentWallet = String(props.connectedAddress || "").toLowerCase() === String(props.address || "").toLowerCase();
    const tokenBalance = Number(props.token || 0);
    const superchatBalance = Number(props.tttBalance || 0);
    const rank = Number(props.rank || 0);
    const studentCount = Number(props.num_of_student || 0);
    const registrationDate = props.registrationInfo?.addedAt
        ? new Date(Number(props.registrationInfo.addedAt) * 1000).toLocaleString("ja-JP")
        : "";
    const shortAddedBy = props.registrationInfo?.addedBy
        ? `${props.registrationInfo.addedBy.slice(0, 10)}...${props.registrationInfo.addedBy.slice(-6)}`
        : "未記録";

    const tokenDetails = manualToken || { symbol: "TFT", address: token_address, decimals: 18 };
    const runWalletAction = async (action) => {
        if (operationInFlight.current) return;
        operationInFlight.current = true;
        setBusy(action); setMessage(""); setFailure(null); setManualToken(null);
        try {
            const provider = await props.cont?.getEthereumProviderReady?.() || props.cont?.getEthereumProvider?.();
            setProviderMissing(!provider);
            if (!provider) throw new Error("ethereum_not_found");
            if (action === "network") {
                await props.cont.repair_wallet_network();
                setMessage("Polygon Amoy の通信を確認しました。トークン一覧側のネットワークも Polygon Amoy を選択してください。");
                return;
            }
            const symbol = action === "ttt" ? "TTT" : "TFT";
            const result = action === "ttt" ? await props.cont.add_ttt_token_wallet() : await props.cont.add_token_wallet();
            if (result?.fallback === "manual") {
                setManualToken({ symbol, address: result.address || (action === "ttt" ? ttt_token_address : token_address), decimals: result.decimals ?? 18 });
                setMessage(result.reason === "wallet_network_selection"
                    ? "MetaMaskのウォレット側でも Polygon Amoy を選択してから、もう一度追加してください。手動追加の情報も下に表示しています。"
                    : `${symbol} の自動追加に対応していないため、下の情報でカスタムトークンとして追加してください。`);
            } else if (result?.added === true) {
                setMessage(`MetaMask が ${symbol} の追加を受け付けました。ウォレット側で Polygon Amoy のトークン一覧を確認してください。表示が TOKEN のままなら、このトークンだけを非表示にして再追加できます。残高は変わりません。`);
            } else {
                setMessage(`${symbol} の追加は完了していません。MetaMask の確認画面で追加を承認してください。`);
            }
        } catch (error) {
            setFailure(error);
            setMessage(getWalletErrorMessage(error) || "操作を完了できません。MetaMask の確認画面と Polygon Amoy の接続先を確認してください。");
        } finally { operationInFlight.current = false; setBusy(""); }
    };
    const copyTokenAddress = async () => {
        try {
            const copied = await props.cont.copyTextToClipboard(tokenDetails.address);
            setMessage(copied ? `${tokenDetails.symbol} のアドレスをコピーしました。` : "コピーできませんでした。表示中のコントラクトアドレスを選択してください。");
        } catch (_) { setMessage("コピーできませんでした。表示中のコントラクトアドレスを選択してください。"); }
    };

    return (
        <div className="user-card glass-card animate-slideUp">
            <div className="user-address">
                <span className="user-address-label">アドレス</span>
                <span className="user-address-value">
                    {props.address ? `${props.address.slice(0, 10)}...${props.address.slice(-6)}` : ""}
                </span>
            </div>

            <div className="user-stats">
                <div className="user-stat-item">
                    <div className="user-stat-icon">R</div>
                    <div className="user-stat-info">
                        <span className="user-stat-label">利用区分</span>
                        <span className="user-stat-value">{props.roleInfo?.label || "未登録"}</span>
                    </div>
                </div>
                <div className="user-stat-item">
                    <div className="user-stat-icon">T</div>
                    <div className="user-stat-info">
                        <span className="user-stat-label">保有トークン</span>
                        <span className="user-stat-value">{tokenBalance.toFixed(2)} TFT</span>
                    </div>
                </div>
                <div className="user-stat-item">
                    <div className="user-stat-icon">#</div>
                    <div className="user-stat-info">
                        <span className="user-stat-label">順位</span>
                        <span className="user-stat-value">
                            {rank}位 / {studentCount}人
                        </span>
                    </div>
                </div>
                <div className="user-stat-item">
                    <div className="user-stat-icon">C</div>
                    <div className="user-stat-info">
                        <span className="user-stat-label">スーパーチャット残高</span>
                        <span className="user-stat-value">{superchatBalance.toFixed(2)} TTT</span>
                    </div>
                </div>
                <div className="user-stat-item">
                    <div className="user-stat-icon">A</div>
                    <div className="user-stat-info">
                        <span className="user-stat-label">登録状態</span>
                        <span className="user-stat-value">{props.registrationInfo?.registered ? "登録済み" : "未登録"}</span>
                    </div>
                </div>
                <div className="user-stat-item">
                    <div className="user-stat-icon">W</div>
                    <div className="user-stat-info">
                        <span className="user-stat-label">現在の接続</span>
                        <span className="user-stat-value">{isCurrentWallet ? "現在接続中" : "別アドレスを表示中"}</span>
                    </div>
                </div>
                <div className="user-stat-item">
                    <div className="user-stat-icon">B</div>
                    <div className="user-stat-info">
                        <span className="user-stat-label">追加した人</span>
                        <span className="user-stat-value">{shortAddedBy}</span>
                    </div>
                </div>
                <div className="user-stat-item">
                    <div className="user-stat-icon">D</div>
                    <div className="user-stat-info">
                        <span className="user-stat-label">登録日時</span>
                        <span className="user-stat-value">{registrationDate || "未記録"}</span>
                    </div>
                </div>
                <div className="user-stat-item">
                    <div className="user-stat-icon">S</div>
                    <div className="user-stat-info">
                        <span className="user-stat-label">獲得点数</span>
                        <span className="user-stat-value">{convertTftToPoint(props.result).toFixed(1)}点</span>
                    </div>
                </div>
            </div>

            <div style={{ display: "grid", gap: "12px", marginTop: "var(--space-4)" }}>
                <button type="button" className="btn-ghost" style={{ width: "100%", minHeight: 44 }} disabled={Boolean(busy)} onClick={() => runWalletAction("network")}>
                    <FiWifi aria-hidden="true" />
                    Polygon Amoy を MetaMask に追加
                </button>
                <button type="button" className="btn-ghost" style={{ width: "100%", minHeight: 44 }} disabled={Boolean(busy)} onClick={() => runWalletAction("tft")}>
                    <FiPlusCircle aria-hidden="true" />
                    TFT を MetaMask に追加
                </button>
                <button type="button" className="btn-ghost" style={{ width: "100%", minHeight: 44 }} disabled={Boolean(busy)} onClick={() => runWalletAction("ttt")}>
                    <FiPlusCircle aria-hidden="true" />
                    TTT を MetaMask に追加
                </button>
            </div>
            {busy && <p role="status" aria-live="polite">MetaMaskでネットワークまたはトークン追加を確認してください...</p>}
            {message && <p role={failure ? "alert" : "status"} style={{ marginTop: 12, overflowWrap: "anywhere" }}>{message}</p>}
            <MetaMaskMobileLink providerAvailable={providerMissing ? false : undefined} />
            <WalletRecovery cont={props.cont} error={failure} />
            <details open={Boolean(manualToken)} style={{ marginTop: 12, overflowWrap: "anywhere" }}>
                <summary>{tokenDetails.symbol} の追加情報</summary>
                <dl>
                    <dt>ネットワーク</dt><dd>Polygon Amoy（80002）</dd>
                    <dt>シンボル</dt><dd>{tokenDetails.symbol}</dd>
                    <dt>Decimals</dt><dd>{tokenDetails.decimals}</dd>
                    <dt>コントラクトアドレス</dt><dd style={{ marginLeft: 0, userSelect: "all", overflowWrap: "anywhere" }}><code>{tokenDetails.address}</code></dd>
                </dl>
                <button type="button" className="btn-ghost" style={{ minHeight: 44 }} disabled={Boolean(busy)} aria-label={`${tokenDetails.symbol}のコントラクトアドレスをコピー`} title="コントラクトアドレスをコピー" onClick={copyTokenAddress}><FiCopy aria-hidden="true" /></button>
            </details>
        </div>
    );
}

export default User_card;
